import math, logging
from concurrent.futures import ProcessPoolExecutor
def _factorial(n):
return math.factorial(n)
def compute_factorials(nums):
logger = logging.getLogger(__name__)
with ProcessPoolExecutor() as exe:
for n, res in zip(nums, exe.map(_factorial, nums)):
logger.info("%d! = %d", n, res)
return list(exe.map(_factorial, nums))
